export const Free: Story = {
  parameters: {
    docs: {
      description: { story: "`navigation="free"` makes every enabled step reachable. Moving forward still runs the guard; with `leaveInvalid="allow"` a step that fails it is marked and left behind, and finishing waits until every step passes." },
      source: { code: "import { useState } from "react";
import { Checkbox } from "@/registry/erbium/ui/checkbox";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import {
  Stepper,
  StepperActions,
  StepperIndicator,
  StepperItem,
  StepperList,
  StepperNext,
  StepperPanel,
  StepperPrevious,
  StepperSeparator,
  StepperText,
  StepperTitle,
  StepperTrigger,
} from "@/registry/erbium/ui/stepper";
import type { StepperGuard } from "@/registry/erbium/ui/stepper";

const steps = [
  { id: "general", title: "General" },
  { id: "privacy", title: "Privacy" },
  { id: "billing", title: "Billing" },
];

// Free navigation: any step can be opened. Leaving a step forward still checks it, and with
// leaveInvalid="allow" an unchecked step is marked but does not hold the user back. Finishing
// still needs every step valid.
export default function StepperFreeExample() {
  const [accepted, setAccepted] = useState<Record<string, boolean>>({});
  const guard: StepperGuard = ({ step }) => accepted[step];

  return (
    <Stepper
      steps={steps}
      navigation="free"
      leaveInvalid="allow"
      guard={guard}
      className="max-w-lg"
    >
      <StepperList aria-label="Settings">
        {steps.map((step) => (
          <StepperItem key={step.id} value={step.id}>
            <StepperTrigger>
              <StepperIndicator />
              <StepperText>
                <StepperTitle>{step.title}</StepperTitle>
              </StepperText>
            </StepperTrigger>
            <StepperSeparator />
          </StepperItem>
        ))}
      </StepperList>
      {steps.map((step) => (
        <StepperPanel key={step.id} value={step.id}>
          <Field orientation="horizontal">
            <Checkbox
              checked={accepted[step.id]}
              onCheckedChange={(checked) => {
                setAccepted((current) => ({ ...current, [step.id]: checked }));
              }}
            />
            <FieldLabel>{step.title} settings reviewed</FieldLabel>
          </Field>
        </StepperPanel>
      ))}
      <StepperActions>
        <StepperPrevious />
        <StepperNext />
      </StepperActions>
    </Stepper>
  );
}
" },
    },
  },
  render: FreeExample,
};

export const AsyncGuard: Story = {
  parameters: {
    docs: {
      description: { story: "A guard can return a promise. Next shows a spinner and stays focusable with `aria-busy` while it runs, and a second click is ignored. The guard's `signal` aborts if the move is cancelled." },
      source: { code: "import { useState } from "react";
import { Input } from "@/registry/erbium/ui/input";
import {
  Stepper,
  StepperActions,
  StepperIndicator,
  StepperItem,
  StepperList,
  StepperNext,
  StepperPanel,
  StepperPrevious,
  StepperSeparator,
  StepperText,
  StepperTitle,
  StepperTrigger,
} from "@/registry/erbium/ui/stepper";
import type { StepperGuard } from "@/registry/erbium/ui/stepper";

const steps = [
  { id: "handle", title: "Handle" },
  { id: "confirm", title: "Confirm" },
];

const taken = new Set(["admin", "erbium", "root"]);

/** Waits `ms`, or less if `signal` aborts first. */
const wait = async (ms: number, signal: AbortSignal) => {
  // oxlint-disable-next-line promise/avoid-new -- browsers have no promise-based timer, so the delay wraps `setTimeout`.
  await new Promise<void>((resolve) => {
    const timer = setTimeout(resolve, ms);

    signal.addEventListener("abort", () => {
      clearTimeout(timer);
      resolve();
    });
  });
};

/** Stands in for a server check. Aborting it stops the wait. */
const isAvailable = async (handle: string, signal: AbortSignal) => {
  await wait(900, signal);
  signal.throwIfAborted();

  return !taken.has(handle.trim().toLowerCase());
};

export default function StepperAsyncGuardExample() {
  const [handle, setHandle] = useState("admin");

  // Next waits for the check. Clicking again while it runs is ignored, and the buttons stay
  // focusable with aria-busy.
  const guard: StepperGuard = async ({ signal, step }) =>
    step === "handle" ? await isAvailable(handle, signal) : true;

  return (
    <Stepper steps={steps} guard={guard} className="max-w-sm">
      <StepperList aria-label="Claim a handle">
        {steps.map((step) => (
          <StepperItem key={step.id} value={step.id}>
            <StepperTrigger>
              <StepperIndicator />
              <StepperText>
                <StepperTitle>{step.title}</StepperTitle>
              </StepperText>
            </StepperTrigger>
            <StepperSeparator />
          </StepperItem>
        ))}
      </StepperList>
      <StepperPanel value="handle" className="flex flex-col gap-related">
        <Input
          aria-label="Handle"
          value={handle}
          onChange={(event) => {
            setHandle(event.target.value);
          }}
        />
        <p className="text-control-sm text-muted-foreground">admin, erbium and root are taken.</p>
      </StepperPanel>
      <StepperPanel value="confirm" className="text-control">
        @{handle} is yours.
      </StepperPanel>
      <StepperActions>
        <StepperPrevious />
        <StepperNext />
      </StepperActions>
    </Stepper>
  );
}
" },
    },
  },
  render: AsyncGuardExample,
};

export const TanstackForm: Story = {
  parameters: {
    docs: {
      description: { story: "One Effect Schema describes the whole form. Each step is a `form.FormGroup` named after the step, with its slice of the schema, inside a `StepperForm`.

- **Next and Enter submit the step's group.** Its fields are touched and validated, invalid ones shake, and the first takes focus.
- **An untouched optional step is skipped**, not completed.
- **Editing a completed answer reopens the step** and every later one.
- **The final submit runs the whole schema, then the server.** `createStepperFormFinish` returns to the first step with errors. Here a taken email comes back from the server and lands on its field." },
      source: { code: "import { Schema } from "effect";
import { useAppForm } from "@/registry/erbium/ui/form";
import {
  createStepperFormFinish,
  Stepper,
  StepperActions,
  StepperForm,
  StepperIndicator,
  StepperItem,
  StepperList,
  StepperNext,
  StepperOptional,
  StepperPanel,
  StepperPrevious,
  StepperSeparator,
  StepperText,
  StepperTitle,
  StepperTrigger,
} from "@/registry/erbium/ui/stepper";

const Required = Schema.Trim.check(Schema.isNonEmpty({ message: "Required" }));

const Account = Schema.Struct({
  email: Schema.String.check(
    Schema.isPattern(/^[^\s@]+@[^\s@.]+(?:\.[^\s@.]+)+$/u, {
      message: "Enter a valid email address.",
    }),
  ),
});

const Profile = Schema.Struct({ name: Required });

const Referral = Schema.Struct({ code: Schema.String });

// One schema for the whole form. Each step validates its own slice, named after the step.
const Signup = Schema.Struct({ account: Account, profile: Profile, referral: Referral });

const steps = [
  { id: "account", title: "Account" },
  { id: "referral", optional: true, title: "Referral" },
  { id: "profile", title: "Profile" },
];

/** Stands in for the server: this address is already registered. */
const register = async (email: string) => {
  // oxlint-disable-next-line promise/avoid-new -- browsers have no promise-based timer, so the delay wraps `setTimeout`.
  await new Promise((resolve) => {
    setTimeout(resolve, 600);
  });

  if (email === "taken@example.com") {
    throw new Error("email-taken");
  }
};

export default function StepperTanstackFormExample() {
  const form = useAppForm({
    defaultValues: { account: { email: "" }, profile: { name: "" }, referral: { code: "" } },
    validators: { onDynamic: Schema.toStandardSchemaV1(Signup) },
    onSubmit: async ({ value }) => {
      await register(value.account.email);
    },
  });

  return (
    <Stepper
      steps={steps}
      className="max-w-md"
      // The final submit runs the whole schema, then the server. A taken email sends the user
      // back to the account step with the error on its field.
      onFinish={createStepperFormFinish(form, {
        fieldErrors: (error) =>
          error instanceof Error && error.message === "email-taken"
            ? { "account.email": "That email is already registered." }
            : undefined,
      })}
    >
      <StepperList aria-label="Sign up">
        {steps.map((step) => (
          <StepperItem key={step.id} value={step.id}>
            <StepperTrigger>
              <StepperIndicator />
              <StepperText>
                <StepperTitle>{step.title}</StepperTitle>
                <StepperOptional />
              </StepperText>
            </StepperTrigger>
            <StepperSeparator />
          </StepperItem>
        ))}
      </StepperList>
      <StepperPanel value="account">
        <form.FormGroup
          name="account"
          validators={{ onDynamic: Schema.toStandardSchemaV1(Account) }}
        >
          {(group) => (
            <StepperForm group={group}>
              <form.AppField name="account.email">
                {(field) => <field.TextField label="Email" required />}
              </form.AppField>
              <p className="text-control-sm text-muted-foreground">
                Try taken@example.com to see a server error routed back here.
              </p>
            </StepperForm>
          )}
        </form.FormGroup>
      </StepperPanel>
      <StepperPanel value="referral">
        <form.FormGroup
          name="referral"
          validators={{ onDynamic: Schema.toStandardSchemaV1(Referral) }}
        >
          {(group) => (
            // Left empty, Next skips the step instead of completing it.
            <StepperForm group={group}>
              <form.AppField name="referral.code">
                {(field) => <field.TextField label="Referral code" />}
              </form.AppField>
            </StepperForm>
          )}
        </form.FormGroup>
      </StepperPanel>
      <StepperPanel value="profile">
        <form.FormGroup
          name="profile"
          validators={{ onDynamic: Schema.toStandardSchemaV1(Profile) }}
        >
          {(group) => (
            <StepperForm group={group}>
              <form.AppField name="profile.name">
                {(field) => <field.TextField label="Name" required />}
              </form.AppField>
            </StepperForm>
          )}
        </form.FormGroup>
      </StepperPanel>
      <StepperActions>
        <StepperPrevious />
        <StepperNext finishLabel="Create account" />
      </StepperActions>
    </Stepper>
  );
}
" },
    },
  },
  render: TanstackFormExample,
};

export const Controlled: Story = {
  parameters: {
    docs: {
      description: { story: "Pass `value` and `onValueChange`. A value the flow cannot reach, such as a deep link past unfinished steps, is refused: `onValueChange` answers with the step it stays on and the reason `unreachable`." },
      source: { code: "import { useState } from "react";
import { Button } from "@/registry/erbium/ui/button";
import {
  Stepper,
  StepperActions,
  StepperIndicator,
  StepperItem,
  StepperList,
  StepperNext,
  StepperPanel,
  StepperPrevious,
  StepperSeparator,
  StepperText,
  StepperTitle,
  StepperTrigger,
} from "@/registry/erbium/ui/stepper";

const steps = [
  { id: "cart", title: "Cart" },
  { id: "shipping", title: "Shipping" },
  { id: "payment", title: "Payment" },
];

// The value can live anywhere, such as a `?step=` search param. A value the flow cannot reach
// yet, like a deep link to payment, is refused: `onValueChange` answers with the step it is on.
export default function StepperControlledExample() {
  const [step, setStep] = useState("payment");
  const [log, setLog] = useState<string[]>([]);

  return (
    <div className="flex max-w-lg flex-col gap-section">
      <Stepper
        steps={steps}
        value={step}
        onValueChange={(next, details) => {
          setStep(next);
          setLog((entries) =>
            [`${details.from} → ${next} (${details.reason})`, ...entries].slice(0, 4),
          );
        }}
      >
        <StepperList aria-label="Checkout">
          {steps.map((item) => (
            <StepperItem key={item.id} value={item.id}>
              <StepperTrigger>
                <StepperIndicator />
                <StepperText>
                  <StepperTitle>{item.title}</StepperTitle>
                </StepperText>
              </StepperTrigger>
              <StepperSeparator />
            </StepperItem>
          ))}
        </StepperList>
        {steps.map((item) => (
          <StepperPanel
            key={item.id}
            value={item.id}
            className="text-control text-muted-foreground"
          >
            {item.title}
          </StepperPanel>
        ))}
        <StepperActions>
          <StepperPrevious />
          <StepperNext />
        </StepperActions>
      </Stepper>
      <div className="flex flex-col gap-related">
        <Button
          variant="outline"
          size="sm"
          className="self-start"
          onClick={() => {
            setStep("payment");
          }}
        >
          Deep link to payment
        </Button>
        <ul className="text-control-sm text-muted-foreground tabular-nums">
          {log.map((entry, index) => (
            // Entries repeat, and the newest is always first.
            // oxlint-disable-next-line react-doctor/no-array-index-as-key -- a short rolling log; position is its identity.
            <li key={index}>{entry}</li>
          ))}
        </ul>
      </div>
    </div>
  );
}
" },
    },
  },
  render: ControlledExample,
};

export const Dynamic: Story = {
  parameters: {
    docs: {
      description: { story: "Toggle a step's `disabled` from earlier answers. The last step here is a `review`, which opens only when every other step is done." },
      source: { code: "import { useState } from "react";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { Switch } from "@/registry/erbium/ui/switch";
import {
  Stepper,
  StepperActions,
  StepperIndicator,
  StepperItem,
  StepperList,
  StepperNext,
  StepperPanel,
  StepperPrevious,
  StepperSeparator,
  StepperText,
  StepperTitle,
  StepperTrigger,
} from "@/registry/erbium/ui/stepper";

export default function StepperDynamicExample() {
  const [business, setBusiness] = useState(false);

  // A step that only applies to some answers is disabled, not removed, so its status survives
  // when it comes back. The last step reviews the others and opens only once they are done.
  const steps = [
    { id: "account", title: "Account" },
    { disabled: !business, id: "company", title: "Company" },
    { id: "review", review: true, title: "Review" },
  ];

  return (
    <Stepper steps={steps} className="max-w-lg">
      <StepperList aria-label="Sign up">
        {steps.flatMap((step) =>
          step.disabled === true
            ? []
            : [
                <StepperItem key={step.id} value={step.id}>
                  <StepperTrigger>
                    <StepperIndicator />
                    <StepperText>
                      <StepperTitle>{step.title}</StepperTitle>
                    </StepperText>
                  </StepperTrigger>
                  <StepperSeparator />
                </StepperItem>,
              ],
        )}
      </StepperList>
      <StepperPanel value="account">
        <Field orientation="horizontal">
          <Switch checked={business} onCheckedChange={setBusiness} />
          <FieldLabel>This is a business account</FieldLabel>
        </Field>
      </StepperPanel>
      <StepperPanel value="company" className="text-control text-muted-foreground">
